+    roundCoord(const Point* pt, const PrecisionModel* p_pm)
+    {
+        const Coordinate* p = pt->getCoordinate();
+        if (OverlayUtil::isFloating(p_pm))
+            return *p;
+        Coordinate p2 = *p;
+        p_pm->makePrecise(p2);
+        return p2;
+    }
+
+private:
+    std::map<Coordinate, std::unique_ptr<Point>>& ptMap;
+    const PrecisionModel* pm;
